def direct_case_files(images_root, uid, allowed):
    study_root = images_root / uid
    expected_series = {x['series_uid'] for x in allowed}
    observed_series = {p.name for p in study_root.iterdir() if p.is_dir()}
    if observed_series != expected_series:
        raise ValueError(f'{uid}: competition series directories differ from train_series.csv')
    for series in allowed:
        folder = study_root / series['series_uid']
        files = sorted(folder.glob('*.dcm'))
        if not files or len(files) != sum(p.is_file() for p in folder.iterdir()):
            raise ValueError(f'{uid}/{series["series_uid"]}: empty or unexpected DICOM files')
        for path in files:
            yield str(path.relative_to(images_root.parent)), path.read_bytes()


def load_case_direct(images_root, uid, allowed):
    """The Gold load_case math, with competition files replacing tar members."""
    groups = {s['series_uid']: [] for s in allowed}; pix = {}
    for member, raw in direct_case_files(images_root, uid, allowed):
        d = pydicom.dcmread(io.BytesIO(raw))
        assert str(d.StudyInstanceUID) == uid
        suid = str(d.SeriesInstanceUID)
        assert suid in groups
        assert int(getattr(d, 'NumberOfFrames', 1)) == 1
        row = {k: scalar(d, k) for k in TAGS}
        row.update(member=member, source_sha256=hashlib.sha256(raw).hexdigest())
        iop = np.array(row['ImageOrientationPatient'], float); ipp = np.array(row['ImagePositionPatient'], float)
        normal = np.cross(iop[:3], iop[3:]); assert abs(np.linalg.norm(normal) - 1) < 0.01
        assert row['PhotometricInterpretation'] in ['MONOCHROME1', 'MONOCHROME2'] and int(row['SamplesPerPixel']) == 1
        row['physical_coordinate'] = float(np.dot(ipp, normal)); row['normal'] = normal.tolist()
        slope = float(getattr(d, 'RescaleSlope', 1) or 1); intercept = float(getattr(d, 'RescaleIntercept', 0) or 0)
        pix[member] = d.pixel_array.astype(np.float32) * slope + intercept
        groups[suid].append(row)
    series = []
    for n, s in enumerate(allowed, 1):
        rows = sorted(groups[s['series_uid']], key=lambda r: r['physical_coordinate'])
        assert rows, ('empty series', s['series_uid'])
        assert len({r['physical_coordinate'] for r in rows}) == len(rows)
        assert len({(r['Rows'], r['Columns'], str(r['PixelSpacing'])) for r in rows}) == 1
        normal = rows[0]['normal']; plane = ['Sagittal', 'Coronal', 'Axial'][int(np.argmax(np.abs(normal)))]
        assert plane == s['anatomical_plane'], (s['series_uid'], plane, s['anatomical_plane'])
        for i, r in enumerate(rows): r['physical_index'] = i
        series.append(dict(s, series_id=f"{s['case_id']}_S{n}", n_frames=len(rows),
                           steps_mm=np.diff([r['physical_coordinate'] for r in rows]).tolist(), frames=rows,
                           arrays=[pix[r['member']] for r in rows]))
    return series


def competition_root():
    override = os.environ.get('RSNA_COMP_ROOT')
    options = [Path(override)] if override else [
        Path('/kaggle/input/competitions/rsna-knee-abnormality-detection'),
        Path('/kaggle/input/rsna-knee-abnormality-detection'),
    ]
    for root in options:
        if all((root / name).exists() for name in ('train.csv', 'train_series.csv', 'train_series')):
            return root
    raise FileNotFoundError('RSNA competition train.csv/train_series.csv/train_series not mounted')


def metadata(root):
    train_path, series_path = root / 'train.csv', root / 'train_series.csv'
    if sha(train_path) != TRAIN_SHA256 or sha(series_path) != SERIES_SHA256:
        raise ValueError('competition metadata SHA-256 does not match frozen train source')
    reports = {}
    with train_path.open(newline='') as f:
        rows = csv.reader(f); header = next(rows)
        uid_pos, report_pos = header.index('StudyInstanceUID'), header.index('Report')
        for row in rows:
            uid, report = row[uid_pos], row[report_pos]
            if uid in reports: raise ValueError(f'duplicate study UID {uid}')
            reports[uid] = report
    allowed_by_uid = {}
    seen_series = set()
    with series_path.open(newline='') as f:
        rows = csv.DictReader(f)
        if rows.fieldnames != ['StudyInstanceUID', 'SeriesInstanceUID', 'Fluid_Sensitive', 'Fat_Suppression', 'Anatomical_Plane']:
            raise ValueError('unexpected train_series schema')
        for row in rows:
            uid, suid = row['StudyInstanceUID'], row['SeriesInstanceUID']
            if suid in seen_series: raise ValueError(f'duplicate series UID {suid}')
            seen_series.add(suid)
            allowed_by_uid.setdefault(uid, []).append({
                'series_uid': suid, 'fluid_sensitive': row['Fluid_Sensitive'],
                'fat_suppression': row['Fat_Suppression'], 'anatomical_plane': row['Anatomical_Plane'],
            })
    if len(reports) != 4407 or len(seen_series) != 24371 or set(reports) != set(allowed_by_uid):
        raise ValueError('training source coverage differs from 4407 studies / 24371 series')
    if not GOLD_UIDS <= set(reports) or len(GOLD_UIDS) != 58:
        raise ValueError('Gold exclusion UID set invalid')
    if len(BILATERAL_UIDS) != 7 or not BILATERAL_UIDS <= set(reports) or GOLD_UIDS & BILATERAL_UIDS:
        raise ValueError('dual-knee manual queue mismatch')
    remaining = sorted(set(reports) - GOLD_UIDS - BILATERAL_UIDS,
                       key=lambda uid: hashlib.sha256((SCOPE_SEED + ':' + uid).encode()).hexdigest())
    if len(remaining) != 4342:
        raise ValueError('single-knee non-Gold study count differs from 4342')
    selected = remaining[(SHARD_NUMBER - 1) * 600:SHARD_NUMBER * 600]
    digest = hashlib.sha256(('\n'.join(selected) + '\n').encode()).hexdigest()
    if digest != EXPECTED_SHARD_UID_SHA256:
        raise ValueError('shard UID order differs from frozen local scope')
    return reports, allowed_by_uid, selected


def render_case(case_id, uid, report, allowed, images_root, case_dir):
    t0 = time.time()
    case_dir.joinpath('panels').mkdir(parents=True, exist_ok=False)
    source_series = [dict(s, case_id=case_id, study_uid=uid) for s in allowed]
    series = load_case_direct(images_root, uid, source_series)
    menu = select_detail(series)
    predicted = sum(math.ceil(s['n_frames'] / 16) for s in series) + sum(math.ceil(len(m['indices']) / 4) for m in menu)
    dropped = []; used = {m['series_id'] for m in menu}; skip_overview = set()
    if predicted > BUDGET:
        for s in series:
            if s['fluid_sensitive'] == '0' and s['series_id'] not in used and predicted > BUDGET:
                skip_overview.add(s['series_id']); predicted -= math.ceil(s['n_frames'] / 16)
                dropped.append(f"overview:{s['series_id']}")
    if predicted > BUDGET:
        for item in [m for m in menu if m['mode'] == 'axial_second_window']:
            if predicted <= BUDGET: break
            menu.remove(item); predicted -= math.ceil(len(item['indices']) / 4)
            dropped.append(f"axial_second_window:{item['series_id']}")
    panels = []; windows = {}
    for s in series:
        if s['series_id'] in skip_overview:
            windows[s['series_id']] = window(s['arrays']); continue
        recs, w = overview_panels(case_id, s, case_dir)
        panels.extend(recs); windows[s['series_id']] = w
    panels.extend(detail_panels(case_id, series, menu, case_dir, windows))
    if len({p['panel_id'] for p in panels}) != len(panels) or len(panels) != predicted:
        raise ValueError(f'{case_id}: panel count/order mismatch after render')
    reader_input = {
        'case_id': case_id, 'study_uid': uid,
        'series': [
            {'series_id': s['series_id'], 'plane': s['anatomical_plane'],
             'fluid_sensitive': s['fluid_sensitive'], 'frames': s['n_frames'],
             'physical_step_mm': step(s)} for s in series
        ],
        'panel_count': len(panels),
        'panels': [
            {'order': i + 1, 'panel_id': p['panel_id'],
             'file': f'panels/{p["panel_id"]}.png', 'mode': p['mode'],
             'series_id': p['series_id'], 'indices': p['indices'], 'window': p['window'],
             'tile_px': p['tile_px'], 'png_dimensions': p['dimensions']}
            for i, p in enumerate(panels)
        ],
    }
    budget_exception = (len(panels) > BUDGET)
    case_dir.joinpath('READER_INPUT.json').write_text(json.dumps(reader_input, ensure_ascii=False, indent=2) + '\n')
    case_dir.joinpath('REPORT.txt').write_text(report)
    panel_receipts = [{'panel_id': p['panel_id'], 'sha256': p['sha256'], 'mode': p['mode'],
                       'source_frame_sha256': [f['source_sha256'] for f in p['frames']]}
                      for p in panels]
    for s in series: s['arrays'] = None
    return {'case_id': case_id, 'study_uid': uid, 'panel_count': len(panels),
            'panel_bytes': sum((case_dir / 'panels' / f"{p['panel_id']}.png").stat().st_size for p in panels),
            'report_sha256': hashlib.sha256(report.encode()).hexdigest(),
            'series_count': len(series), 'panels_dropped_for_budget': dropped,
            'panel_budget_exception': budget_exception,
            'panels': panel_receipts, 'render_seconds': round(time.time() - t0, 2)}


def bundle_assignments(case_ids):
    out = {}
    for i in range(0, len(case_ids), 30):
        batch_number = i // 30 + 1
        batch = case_ids[i:i + 30]
        partitions = (batch[:8], batch[8:16], batch[16:23], batch[23:30])
        for j, part in enumerate(partitions, 1):
            for case_id in part:
                out[case_id] = (f'S{SHARD_NUMBER:02d}B{batch_number:02d}',
                                f'S{SHARD_NUMBER:02d}B{batch_number:02d}_{j:02d}.zip')
    return out


def add_case_to_bundle(case_dir, bundle_path, case_id):
    first = not bundle_path.exists()
    with ZipFile(bundle_path, 'w' if first else 'a', compression=ZIP_STORED, allowZip64=True) as archive:
        if first:
            for name, encoded in SHARED_DOCS_BASE64.items():
                archive.writestr(name, base64.b64decode(encoded))
        for path in [case_dir / 'READER_INPUT.json', case_dir / 'REPORT.txt',
                     *sorted((case_dir / 'panels').glob('*.png'))]:
            archive.write(path, arcname=f'cases/{case_id}/{path.relative_to(case_dir)}')


def seal_bundle(bundle_path, batch_id, receipts):
    case_receipts = [r for r in receipts if r['bundle_name'] == bundle_path.name]
    if not case_receipts:
        raise ValueError(f'empty bundle {bundle_path.name}')
    bundle_index = {
        'batch_id': batch_id,
        'bundle_id': bundle_path.stem,
        'case_order': [r['case_id'] for r in case_receipts],
        'cases': [
            {'case_id': r['case_id'], 'study_uid': r['study_uid'],
             'panel_count': r['panel_count'], 'report_sha256': r['report_sha256']}
            for r in case_receipts
        ],
    }
    with ZipFile(bundle_path, 'a', compression=ZIP_STORED, allowZip64=True) as archive:
        archive.writestr('BUNDLE_INDEX.json', json.dumps(bundle_index, ensure_ascii=False,
                                                       separators=(',', ':')))
    return bundle_index


def bulk_main():
    root = competition_root()
    reports, allowed_by_uid, selected = metadata(root)
    output = Path(os.environ.get('RSNA_OUTPUT_ROOT', '/kaggle/working'))
    scratch = Path(os.environ.get('RSNA_SCRATCH_ROOT', '/kaggle/tmp/rsna-web-panels'))
    output.mkdir(parents=True, exist_ok=True)
    scratch.mkdir(parents=True, exist_ok=True)
    if any(output.glob('S??B??_??.zip')) or (output / 'OUTPUT_MANIFEST.json').exists():
        raise ValueError('output directory already contains shard artifacts; refusing to overwrite')
    case_ids = [f'T{i:04d}' for i in range((SHARD_NUMBER - 1) * 600 + 1,
                                          (SHARD_NUMBER - 1) * 600 + len(selected) + 1)]
    assignment = bundle_assignments(case_ids)
    receipts = []; render_failures = []
    for case_id, uid in zip(case_ids, selected):
        work = scratch / case_id
        if work.exists(): raise ValueError(f'scratch case directory already exists: {work}')
        try:
            receipt = render_case(case_id, uid, reports[uid], allowed_by_uid[uid], root / 'train_series', work)
        except Exception as exc:
            render_failures.append({'case_id': case_id, 'study_uid': uid,
                                    'exception_type': type(exc).__name__,
                                    'reason': str(exc)[:300]})
            if work.exists(): shutil.rmtree(work)
            print(f'{case_id}: RENDER_FAILURE {type(exc).__name__}: {str(exc)[:160]}', flush=True)
            continue
        batch_id, bundle_name = assignment[case_id]
        receipt.update(batch_id=batch_id, bundle_name=bundle_name)
        bundle_path = output / bundle_name
        case_bytes = sum(p.stat().st_size for p in work.rglob('*') if p.is_file())
        if bundle_path.exists() and bundle_path.stat().st_size + case_bytes >= 449_000_000:
            raise RuntimeError(f'{bundle_name} would exceed 450 MB with {case_id}; '
                               'incomplete shard output must not be used')
        add_case_to_bundle(work, bundle_path, case_id)
        shutil.rmtree(work)
        receipts.append(receipt)
        output_bytes = sum(p.stat().st_size for p in output.glob('S??B??_??.zip'))
        if output_bytes > OUTPUT_BYTE_GUARD:
            raise RuntimeError(f'shard exceeds {OUTPUT_BYTE_GUARD} byte safety guard after {case_id}; incomplete output must not be used')
        print(f'{case_id}: {receipt["panel_count"]} panels, {receipt["panel_bytes"]} panel bytes, '
              f'{bundle_name}, {len(receipts)}/{len(selected)} cases', flush=True)
    bundles = []
    for path in sorted(output.glob('S??B??_??.zip')):
        case_receipts = [r for r in receipts if r['bundle_name'] == path.name]
        index = seal_bundle(path, case_receipts[0]['batch_id'], receipts)
        with ZipFile(path) as archive:
            if archive.testzip() is not None:
                raise ValueError(f'ZIP CRC error: {path}')
            case_ids_in_zip = index['case_order']
            if len(case_ids_in_zip) != len(set(case_ids_in_zip)):
                raise ValueError(f'duplicate case in {path}')
            if 'BUNDLE_INDEX.json' not in archive.namelist():
                raise ValueError(f'bundle index missing from {path}')
            for case_id in case_ids_in_zip:
                if f'cases/{case_id}/READER_INPUT.json' not in archive.namelist():
                    raise ValueError(f'{case_id} reader manifest missing from {path}')
        bundles.append({'filename': path.name, 'sha256': sha(path), 'bytes': path.stat().st_size,
                        'case_order': case_ids_in_zip,
                        'panel_count': sum(r['panel_count'] for r in receipts if r['bundle_name'] == path.name)})
    rendered_ids = {r['case_id'] for r in receipts}
    failed_ids = {f['case_id'] for f in render_failures}
    if (rendered_ids & failed_ids or rendered_ids | failed_ids != set(case_ids)
            or sum(len(b['case_order']) for b in bundles) != len(receipts)):
        raise ValueError('rendered/failed case coverage is incomplete or overlapping')
    if any(b['bytes'] >= 450_000_000 for b in bundles):
        raise ValueError('a bundle is too close to the ChatGPT 512 MB file limit')
    manifest = {
        'status': 'COMPLETE_WITH_RENDER_FAILURES' if render_failures else 'COMPLETE',
        'shard_id': f'S{SHARD_NUMBER:02d}',
        'source': 'rsna-knee-abnormality-detection competition train series',
        'train_csv_sha256': TRAIN_SHA256, 'train_series_csv_sha256': SERIES_SHA256,
        'selected_uid_sha256': EXPECTED_SHARD_UID_SHA256,
        'attempted_case_count': len(selected), 'case_count': len(receipts),
        'render_failure_count': len(render_failures), 'render_failures': render_failures,
        'panel_count': sum(r['panel_count'] for r in receipts),
        'bundle_count': len(bundles), 'bundle_bytes': sum(b['bytes'] for b in bundles),
        'cases': receipts, 'bundles': bundles,
    }
    (output / 'OUTPUT_MANIFEST.json').write_text(json.dumps(manifest, ensure_ascii=False, indent=2) + '\n')
    print(json.dumps({'status': manifest['status'], 'case_count': manifest['case_count'],
                      'render_failure_count': manifest['render_failure_count'],
                      'panel_count': manifest['panel_count'], 'bundle_count': len(bundles),
                      'bundle_bytes': manifest['bundle_bytes']}, ensure_ascii=False), flush=True)


if __name__ == '__main__':
    bulk_main()
